python_code: import sys

def solve_n_queens(n):
    ans = []
    path = [['.' for _ in range(n)] for _ in range(n)]

    def copy_path():
        temp_path = []
        for i in range(len(path)):
            temp_path.append(''.join(path[i]))
        ans.append(temp_path)

    def is_valid(x, y):
        # Check row and column
        for i in range(n):
            if path[y][i] == 'Q' or path[i][x] == 'Q':
                return False

        # Check diagonals
        # Top-left to bottom-right
        i, j = y - 1, x - 1
        while i >= 0 and j >= 0:
            if path[i][j] == 'Q':
                return False
            i -= 1
            j -= 1

        # Bottom-right to top-left
        i, j = y + 1, x + 1
        while i < n and j < n:
            if path[i][j] == 'Q':
                return False
            i += 1
            j += 1

        # Top-right to bottom-left
        i, j = y - 1, x + 1
        while i >= 0 and j < n:
            if path[i][j] == 'Q':
                return False
            i -= 1
            j += 1

        # Bottom-left to top-right
        i, j = y + 1, x - 1
        while i < n and j >= 0:
            if path[i][j] == 'Q':
                return False
            i += 1
            j -= 1

        return True

    def back_tracking(depth):
