def solve_sudoku(board):
    def is_valid(row, col, val, board):
        length = len(board)
        for i in range(length):
            if board[row][i] == val:
                return False
        for i in range(length):
            if board[i][col] == val:
                return False
        start_row = (row // 3) * 3
        start_col = (col // 3) * 3
        for i in range(start_row, start_row + 3):
            for j in range(start_col, start_col + 3):
                if board[i][j] == val:
                    return False
        return True

    def backtracking():
        for i in range(len(board)):
            for j in range(len(board[0])):
                if board[i][j] != '.':
                    continue
                for val in range(1, 10):
                    if is_valid(i, j, str(val), board):
                        board[i][j] = str(val)
                        if backtracking():
                            return True
                        board[i][j] = '.'
                return False
        return True

    backtracking()
    return board

