                        "object"
                    ]
                ],
                "code": "import json\nimport re\n\ndef main(file_obj: dict, llm_response: str):\n    # Extract JSON if wrapped in markdown\n    json_str = llm_response\n    match = re.search(r'\\{.*\\}', llm_response, re.DOTALL)\n    if match:\n        json_str = match.group(0)\n    \n    try:\n        data = json.loads(json_str)\n    except:\n        data = {\"category\": \"UNKNOWN\", \"score\": 0, \"reason\": \"Parsing Error\"}\n        \n    return {\n        \"packed_result\": {\n            \"file\": file_obj,\n            \"category\": data.get(\"category\", \"UNKNOWN\").strip().upper(),\n            \"score\": data.get(\"score\", 0),\n            \"reason\": data.get(\"reason\", \"No reason provided\")\n        }\n    }"
            }
        },
        {
