                        "r_teacher",
                        "string"
                    ]
                ],
                "code": "def main(all_results: list):\n    categories = ['ACCOUNTANT', 'ARTS', 'SALES', 'TEACHER']\n    # Initialize best candidate tracker\n    best = {cat: {'score': -1, 'file': None, 'reason': 'No candidates found.'} for cat in categories}\n    \n    for item in all_results:\n        cat = item.get('category', '')\n        score = item.get('score', 0)\n        \n        # Find matching category bucket\n        for target_cat in categories:\n            if target_cat in cat:\n                if score > best[target_cat]['score']:\n                    best[target_cat] = item\n                break\n    \n    # Prepare outputs\n    final_files = []\n    reasons = {}\n    for cat in categories:\n        if best[cat]['file']:\n            final_files.append(best[cat]['file'])\n            reasons[cat] = f\"(Score: {best[cat]['score']}) {best[cat]['reason']}\"\n        else:\n            reasons[cat] = \"No candidates found.\"\n            \n    return {\n        \"best_resumes\": final_files,\n        \"r_accountant\": reasons['ACCOUNTANT'],\n        \"r_arts\": reasons['ARTS'],\n        \"r_sales\": reasons['SALES'],\n        \"r_teacher\": reasons['TEACHER']\n    }"
